  `tables_count` int(11) NOT NULL DEFAULT 0,
  `rows_count` int(11) NOT NULL DEFAULT 0,
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `created_by` int(10) UNSIGNED NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ix_bl_action`(`action`, `created_at`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- ----------------------------
-- Table structure for bank_reconciliations
-- ----------------------------
DROP TABLE IF EXISTS `bank_reconciliations`;
CREATE TABLE `bank_reconciliations`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `account_id` int(10) UNSIGNED NOT NULL,
  `statement_date` date NOT NULL,
  `beginning_balance` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `ending_balance` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `cleared_balance` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `difference` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `service_charge_txn_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `interest_txn_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `service_charge` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `service_date` date NULL DEFAULT NULL,
  `service_account_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `interest_earned` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `interest_date` date NULL DEFAULT NULL,
  `interest_account_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `class_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `status` enum('in_progress','completed') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_progress',
  `created_by` int(10) UNSIGNED NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `completed_by` int(10) UNSIGNED NULL DEFAULT NULL,
  `completed_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ix_br_account`(`account_id`, `statement_date`) USING BTREE,
  CONSTRAINT `fk_br_account` FOREIGN KEY (`account_id`) REFERENCES `accounts` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

