  `branch_id` int(11) NULL DEFAULT 0,
  `segment_id` int(11) NULL DEFAULT 0,
  `division_id` int(11) NULL DEFAULT 0,
  `is_paid` tinyint(1) NOT NULL DEFAULT 0,
