  `bill_edit_count` int(11) NOT NULL DEFAULT 0,
  `last_bill_edited_at` datetime NULL DEFAULT NULL,
  `last_bill_edited_by` int(11) NULL DEFAULT NULL,
  `deleted_at` datetime NULL DEFAULT NULL,
