-- ----------------------------
-- Table structure for customers
-- ----------------------------
DROP TABLE IF EXISTS `customers`;
CREATE TABLE `customers`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `party_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `parent_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `company_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `contact_person` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `phone` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `mobile` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `email` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `billing_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `shipping_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `tin` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `wht_ids` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `terms_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `credit_limit` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `price_level_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `tax_code_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `payment_method_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `customer_type_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `sales_rep_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `billing_group_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `allow_pos_charge` tinyint(1) NOT NULL DEFAULT 0,
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ix_customers_name`(`name`) USING BTREE,
  INDEX `ix_customers_party`(`party_id`) USING BTREE,
  INDEX `fk_cust_parent`(`parent_id`) USING BTREE,
  INDEX `fk_cust_terms`(`terms_id`) USING BTREE,
  INDEX `fk_cust_pl`(`price_level_id`) USING BTREE,
  INDEX `fk_cust_tax`(`tax_code_id`) USING BTREE,
  INDEX `fk_cust_pm`(`payment_method_id`) USING BTREE,
  INDEX `fk_cust_type`(`customer_type_id`) USING BTREE,
  INDEX `fk_cust_rep`(`sales_rep_id`) USING BTREE,
  INDEX `fk_cust_bg`(`billing_group_id`) USING BTREE,
  CONSTRAINT `fk_cust_parent` FOREIGN KEY (`parent_id`) REFERENCES `customers` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_cust_terms` FOREIGN KEY (`terms_id`) REFERENCES `terms` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_cust_pl` FOREIGN KEY (`price_level_id`) REFERENCES `price_levels` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_cust_tax` FOREIGN KEY (`tax_code_id`) REFERENCES `tax_codes` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_cust_pm` FOREIGN KEY (`payment_method_id`) REFERENCES `payment_methods` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_cust_type` FOREIGN KEY (`customer_type_id`) REFERENCES `customer_types` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_cust_rep` FOREIGN KEY (`sales_rep_id`) REFERENCES `sales_reps` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_cust_bg` FOREIGN KEY (`billing_group_id`) REFERENCES `billing_groups` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 42 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

