  INDEX `fkeybranchID_idx`(`branchid`) USING BTREE,
  INDEX `savAccount_idx`(`branchid`, `memberid`, `savingsid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci;

