  `credit_account_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `receivable_account_id` int(10) UNSIGNED NOT NULL,
  `interest_account_id` int(10) UNSIGNED NOT NULL,
  `penalty_account_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `penalty_rate` decimal(9, 4) NOT NULL DEFAULT 0.0000,
  `penalty_grace_days` int(11) NOT NULL DEFAULT 0,
  `penalty_base` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'arrears',
  `total_interest` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `total_charges` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `net_proceeds` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `previous_loan_payoff` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `status` varchar(14) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'current',
  `principal_balance` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `interest_balance` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `interest_accrued` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `penalty_balance` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `penalty_waived` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `interest_waived` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `last_payment_date` date NULL DEFAULT NULL,
  `last_penalty_date` date NULL DEFAULT NULL,
  `officer_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `release_txn_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `closed_on` date NULL DEFAULT NULL,
  `restructured_to_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `restructured_from_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `written_off_on` date NULL DEFAULT NULL,
  `written_off_txn_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `recovered_amount` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `pb_last_line` int(11) NOT NULL DEFAULT 0,
  `pb_page` int(11) NOT NULL DEFAULT 1,
  `pb_last_txn_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `notes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `created_by` int(10) UNSIGNED NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uq_loan_accounts_no`(`loan_no`) USING BTREE,
  INDEX `ix_loan_accounts_member`(`member_id`) USING BTREE,
  INDEX `ix_loan_accounts_status`(`status`, `due_date`) USING BTREE,
  INDEX `ix_loan_accounts_product`(`product_id`) USING BTREE,
  INDEX `ix_loan_accounts_branch`(`branch_id`) USING BTREE,
  INDEX `ix_loan_accounts_app`(`application_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

