  `branch_id` int(11) NULL DEFAULT NULL,
  `segment_id` int(11) NULL DEFAULT NULL,
  `division_id` int(11) NULL DEFAULT NULL,
  `disconnection_days` int(11) NOT NULL DEFAULT 0,
