  `line_no` int(11) NOT NULL DEFAULT 0,
  `line_kind` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'item',
  `item_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `account_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `qty` decimal(15, 4) NOT NULL DEFAULT 0.0000,
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `uom_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `uom_factor` decimal(15, 6) NOT NULL DEFAULT 1.000000,
  `uom_qty` decimal(15, 4) NOT NULL DEFAULT 0.0000,
  `uom_rate` decimal(15, 4) NOT NULL DEFAULT 0.0000,
  `rate` decimal(15, 4) NOT NULL DEFAULT 0.0000,
  `discount_kind` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pct',
  `discount_pct` decimal(6, 2) NOT NULL DEFAULT 0.00,
  `discount_amount` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `amount` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `tax_code_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `tax_amount` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `site_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `customer_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `vendor_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `is_billable` tinyint(1) NOT NULL DEFAULT 0,
  `billed_txn_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `ref_txn_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `pos_shift_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `source_line_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `qty_fulfilled` decimal(15, 4) NOT NULL DEFAULT 0.0000,
  `amount_fulfilled` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `is_closed` tinyint(1) NOT NULL DEFAULT 0,
  `cost_amount` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `value_change` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `output_role` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `alloc_basis` decimal(15, 4) NOT NULL DEFAULT 0.0000,
  `alloc_pct` decimal(9, 4) NOT NULL DEFAULT 0.0000,
  `planned_qty` decimal(15, 4) NULL DEFAULT NULL,
  `class_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `other_name_id` int(10) UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ix_tl_txn`(`txn_id`) USING BTREE,
  INDEX `ix_tl_item`(`item_id`) USING BTREE,
  INDEX `ix_tl_ref`(`ref_txn_id`) USING BTREE,
  INDEX `ix_tl_shift`(`pos_shift_id`) USING BTREE,
  INDEX `ix_tl_source`(`source_line_id`) USING BTREE,
  INDEX `ix_tl_class`(`class_id`) USING BTREE,
  INDEX `ix_tl_other_name`(`other_name_id`) USING BTREE,
  INDEX `fk_tl_account`(`account_id`) USING BTREE,
  INDEX `fk_tl_tax`(`tax_code_id`) USING BTREE,
  INDEX `fk_tl_site`(`site_id`) USING BTREE,
  INDEX `fk_tl_cust`(`customer_id`) USING BTREE,
  INDEX `fk_tl_uom`(`uom_id`) USING BTREE,
  CONSTRAINT `fk_tl_class` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_tl_other_name` FOREIGN KEY (`other_name_id`) REFERENCES `other_names` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_tl_txn` FOREIGN KEY (`txn_id`) REFERENCES `transactions` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_tl_item` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_tl_account` FOREIGN KEY (`account_id`) REFERENCES `accounts` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_tl_tax` FOREIGN KEY (`tax_code_id`) REFERENCES `tax_codes` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_tl_site` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_tl_cust` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_tl_uom` FOREIGN KEY (`uom_id`) REFERENCES `uom_units` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 825 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

