DROP TABLE IF EXISTS `transactions`;
CREATE TABLE `transactions`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `txn_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `txn_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `txn_date` date NOT NULL,
  `due_date` date NULL DEFAULT NULL,
  `ship_date` date NULL DEFAULT NULL,
  `ref_no` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `customer_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `vendor_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `payee_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `account_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `account2_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `site_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `site2_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `terms_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `sales_rep_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `payment_method_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `billing_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `shipping_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `memo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `customer_message` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `subtotal` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `tax_total` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `discount_amount` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `withholding_amount` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `cash_back_amount` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `total` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `is_pending` tinyint(1) NOT NULL DEFAULT 0,
  `is_voided` tinyint(1) NOT NULL DEFAULT 0,
  `void_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `voided_by` int(10) UNSIGNED NULL DEFAULT NULL,
  `voided_at` datetime NULL DEFAULT NULL,
  `to_be_printed` tinyint(1) NOT NULL DEFAULT 0,
  `is_printed` tinyint(1) NOT NULL DEFAULT 0,
  `restock` tinyint(1) NOT NULL DEFAULT 1,
  `credit_disposition` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `progress_pct` decimal(6, 2) NULL DEFAULT NULL,
  `source_txn_id` bigint(20) UNSIGNED NULL DEFAULT NULL,
  `terminal_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `pos_shift_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `receipt_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `amount_tendered` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `change_given` decimal(15, 2) NOT NULL DEFAULT 0.00,
  `approved_by` int(10) UNSIGNED NULL DEFAULT NULL,
  `batch_ref` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `process_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `alloc_method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `process_formula_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `process_batches` decimal(15, 4) NULL DEFAULT NULL,
  `class_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `other_name_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `party_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `business_unit_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `cp_role` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `cp_name` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `cp_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `cp_tin` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `cp_member_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `cp_source` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `cp_issued_at` datetime NULL DEFAULT NULL,
  `cp_reissue_no` int(11) NOT NULL DEFAULT 0,
  `created_by` int(10) UNSIGNED NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` int(10) UNSIGNED NULL DEFAULT NULL,
  `updated_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ix_txn_type_date`(`txn_type`, `txn_date`) USING BTREE,
  INDEX `ix_txn_customer`(`customer_id`, `txn_date`) USING BTREE,
  INDEX `ix_txn_vendor`(`vendor_id`, `txn_date`) USING BTREE,
  INDEX `ix_txn_status`(`status`) USING BTREE,
  INDEX `ix_txn_source`(`source_txn_id`) USING BTREE,
  INDEX `ix_txn_shift`(`pos_shift_id`) USING BTREE,
  INDEX `ix_txn_formula`(`process_formula_id`) USING BTREE,
  INDEX `ix_txn_class`(`class_id`) USING BTREE,
  INDEX `ix_txn_other_name`(`other_name_id`) USING BTREE,
  INDEX `ix_transactions_party`(`party_id`, `txn_date`) USING BTREE,
  INDEX `ix_transactions_bu`(`business_unit_id`) USING BTREE,
  INDEX `fk_txn_account`(`account_id`) USING BTREE,
  INDEX `fk_txn_account2`(`account2_id`) USING BTREE,
  INDEX `fk_txn_site`(`site_id`) USING BTREE,
  INDEX `fk_txn_site2`(`site2_id`) USING BTREE,
  INDEX `fk_txn_terms`(`terms_id`) USING BTREE,
  INDEX `fk_txn_rep`(`sales_rep_id`) USING BTREE,
  INDEX `fk_txn_pm`(`payment_method_id`) USING BTREE,
  CONSTRAINT `fk_txn_class` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_txn_other_name` FOREIGN KEY (`other_name_id`) REFERENCES `other_names` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_txn_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_txn_vendor` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_txn_account` FOREIGN KEY (`account_id`) REFERENCES `accounts` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_txn_formula` FOREIGN KEY (`process_formula_id`) REFERENCES `process_formulas` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `fk_txn_account2` FOREIGN KEY (`account2_id`) REFERENCES `accounts` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_txn_site` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_txn_site2` FOREIGN KEY (`site2_id`) REFERENCES `sites` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_txn_terms` FOREIGN KEY (`terms_id`) REFERENCES `terms` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_txn_rep` FOREIGN KEY (`sales_rep_id`) REFERENCES `sales_reps` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_txn_pm` FOREIGN KEY (`payment_method_id`) REFERENCES `payment_methods` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 407 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

