INSERT INTO `roles` VALUES (1, 'Administrator', 'Everything in every module, including user accounts, roles, page access, the closing date, and the audit trail.', 1, 1, 1, '2026-10-14 13:01:08', NULL);
INSERT INTO `roles` VALUES (2, 'Accountant', 'Chart of Accounts, Fixed Assets, Banking and reconciliation, the BIR Reports and Withholding Tax Table, all module reports, and the financial statements.', 0, 1, 1, '2026-10-14 13:01:08', NULL);
INSERT INTO `roles` VALUES (3, 'A/R Clerk', 'Customers module transactions and the Customer and Receivables reports.', 0, 1, 1, '2026-10-14 13:01:08', NULL);
INSERT INTO `roles` VALUES (4, 'A/P Clerk', 'Vendors module transactions, Pay Bills, advances to suppliers, the Vendors and Payables reports, and BIR Form 2307 for suppliers.', 0, 1, 1, '2026-10-14 13:01:08', NULL);
INSERT INTO `roles` VALUES (5, 'Inventory Clerk', 'Items, sites, receiving, adjustments, assembly builds, disassembly and processing orders, stock counts, and inventory quantity reports.', 0, 1, 1, '2026-10-14 13:01:08', NULL);
INSERT INTO `roles` VALUES (6, 'Sales Representative', 'Estimates, sales orders, and invoices, and the Sales reports.', 0, 1, 1, '2026-10-14 13:01:08', NULL);
INSERT INTO `roles` VALUES (7, 'Cashier', 'POS sales, returns, and cash drops at the assigned terminal only.', 0, 1, 0, '2026-10-14 13:01:08', NULL);
INSERT INTO `roles` VALUES (8, 'POS Supervisor', 'Everything a cashier can do, plus approving voids, refunds, price overrides, and large discounts, and running X- and Z-readings.', 0, 1, 1, '2026-10-14 13:01:08', NULL);
INSERT INTO `roles` VALUES (9, 'Auditor', 'View-only access to all transactions, reports, and the audit trail. Cannot create or change anything.', 0, 1, 1, '2026-10-14 13:01:08', NULL);
INSERT INTO `roles` VALUES (10, 'General Manager', 'Opens every cooperative, savings, loan, teller, distribution and compliance page, approves loans and transactions, and sees every report.', 0, 1, 1, '2026-10-14 13:01:09', NULL);
INSERT INTO `roles` VALUES (11, 'Bookkeeper', 'Records cooperative vouchers, posts interest and penalties, runs the subsidiary ledgers and financial reports.', 0, 1, 1, '2026-10-14 13:01:09', NULL);
INSERT INTO `roles` VALUES (12, 'Loan Officer', 'Loan applications, credit investigation, loan release, collection, loan accounts and loan reports.', 0, 1, 1, '2026-10-14 13:01:09', NULL);
INSERT INTO `roles` VALUES (13, 'Credit Committee', 'Reviews and approves loan applications and waivers; views loan reports.', 0, 1, 1, '2026-10-14 13:01:09', NULL);
INSERT INTO `roles` VALUES (14, 'Teller', 'Teller shift, official receipts, savings deposits and withdrawals, loan collection and passbook printing.', 0, 1, 1, '2026-10-14 13:01:09', NULL);
INSERT INTO `roles` VALUES (15, 'Membership Officer', 'Member records, member statements, savings account opening and the member reports.', 0, 1, 1, '2026-10-14 13:01:09', NULL);
INSERT INTO `roles` VALUES (16, 'Collector', 'Loan collection and the collection, due and aging reports.', 0, 1, 1, '2026-10-14 13:01:09', NULL);
INSERT INTO `roles` VALUES (17, 'Branch Manager', 'Everything of the branch: approves savings accounts, withdrawals, loans and waivers, closes teller shifts, and sees the branch reports.', 0, 1, 1, '2026-10-14 13:01:09', NULL);
